        {\n                return false;\n                // this can happen for big numbers\n            }\n        }\n    }\n    final String extra = authorityMatcher.group(PARSE_AUTHORITY_EXTRA);\n    if (extra != null && !extra.trim().isEmpty())\n    {\n        return false;\n    }\n    return true;\n}\n```"
