        final int length = input.length();
        if (length == 0)
        {
            // check there is a last character return input;
        }
        // RFC3490 3.1. 1) // Whenever dots are used as label separators, the following // characters MUST be recognized as dots: U+002E (full stop), U+3002 // (ideographic full stop), U+FF0E (fullwidth full stop), U+FF61 // (halfwidth ideographic full stop). final char lastChar = input.charAt(length - 1);
