    // we start with one which is our minimum, and because we do the // first division outside the loop int lettersSoFar = 1;
    // the first division takes into account that the doNotEncode // letters can't be in the leftmost place int lettersLeft = (originalCopy.size() - doNotEncodeCopy.size()) / (encodingCopy.size() - doNotEncodeCopy.size());
    while (lettersLeft / encodingCopy.size() >= 1)
