private StrBuilder replaceImpl(final StrMatcher matcher, final String replaceStr, final int from, int to, int replaceCount)  {
    if (matcher == null || size == 0)
    {
        return this;
    }
    final int replaceLen = replaceStr == null ? 0 : replaceStr.length();
    for (int i = from;
    i < to && replaceCount != 0;
